-- 0023: schema reconcile — make ANY database (empty, or production with hand-applied drift) match
-- drizzle/schema.ts. Generated by scripts/dev/gen-reconcile.mjs from a fresh drizzle-kit dump; do not
-- hand-edit table/column blocks — regenerate instead. Three layers, each idempotent:
--   1. CREATE TABLE IF NOT EXISTS for every table (covers the ~44 tables no migration ever created)
--   2. guarded ADD COLUMN for every column of every table (covers columns added by one-off scripts)
--   3. targeted enum / nullability fixes (status enums, users.role, candidates.email, column widenings)
-- MySQL 8 / TiDB. NOT NULL columns added to non-empty tables fill with the type's zero value.

-- ── 1. tables ──
CREATE TABLE IF NOT EXISTS `academy_assignments` (
	`id` int AUTO_INCREMENT NOT NULL,
	`courseId` int NOT NULL,
	`traineeCode` varchar(100) NOT NULL,
	`crdts` varchar(100),
	`dueDate` varchar(10),
	`assignedBy` varchar(255),
	`status` enum('suggested','assigned','in_progress','completed') NOT NULL DEFAULT 'assigned',
	`reason` varchar(255),
	`assignedAt` bigint NOT NULL,
	`completedAt` bigint,
	`score` int,
	CONSTRAINT `academy_assignments_id` PRIMARY KEY(`id`)
);
CREATE TABLE IF NOT EXISTS `academy_courses` (
	`id` int AUTO_INCREMENT NOT NULL,
	`title` varchar(255) NOT NULL,
	`description` text,
	`category` varchar(100),
	`coverUrl` text,
	`remediesViolation` varchar(150),
	`isMandatory` boolean NOT NULL DEFAULT false,
	`isPublished` boolean NOT NULL DEFAULT false,
	`passMark` int DEFAULT 0,
	`createdBy` varchar(255),
	`createdAt` bigint NOT NULL,
	`updatedAt` bigint,
	CONSTRAINT `academy_courses_id` PRIMARY KEY(`id`)
);
CREATE TABLE IF NOT EXISTS `academy_modules` (
	`id` int AUTO_INCREMENT NOT NULL,
	`courseId` int NOT NULL,
	`title` varchar(255) NOT NULL,
	`contentType` enum('video','pdf','link','text') NOT NULL DEFAULT 'text',
	`contentUrl` text,
	`body` text,
	`durationMins` int DEFAULT 0,
	`sortOrder` int NOT NULL DEFAULT 0,
	`createdAt` bigint NOT NULL,
	CONSTRAINT `academy_modules_id` PRIMARY KEY(`id`)
);
CREATE TABLE IF NOT EXISTS `academy_progress` (
	`id` int AUTO_INCREMENT NOT NULL,
	`traineeCode` varchar(100) NOT NULL,
	`courseId` int NOT NULL,
	`moduleId` int NOT NULL,
	`completedAt` bigint NOT NULL,
	CONSTRAINT `academy_progress_id` PRIMARY KEY(`id`)
);
CREATE TABLE IF NOT EXISTS `academy_quiz_questions` (
	`id` int AUTO_INCREMENT NOT NULL,
