);
CREATE TABLE IF NOT EXISTS `commissions` (
	`id` int AUTO_INCREMENT NOT NULL,
	`crdts` varchar(50) NOT NULL,
	`alias` varchar(255),
	`commissionEgp` decimal(10,2) NOT NULL DEFAULT '0',
