	`note` text NOT NULL,
	`recruiterName` varchar(255),
	`createdAt` timestamp NOT NULL DEFAULT (now()),
	CONSTRAINT `stage_notes_id` PRIMARY KEY(`id`)
);
CREATE TABLE IF NOT EXISTS `team_leaders` (
	`id` int AUTO_INCREMENT NOT NULL,
	`name` varchar(255) NOT NULL,
	`email` varchar(320),
	`phone` varchar(64),
	`isActive` boolean NOT NULL DEFAULT true,
	`createdAt` timestamp NOT NULL DEFAULT (now()),
	CONSTRAINT `team_leaders_id` PRIMARY KEY(`id`),
	CONSTRAINT `team_leaders_name_unique` UNIQUE(`name`)
);
CREATE TABLE IF NOT EXISTS `trainee_code_ledger` (
	`code` varchar(100) NOT NULL,
	`candidateId` int,
	`source` varchar(40) NOT NULL DEFAULT 'backfill',
