	`releasedAt` bigint,
	CONSTRAINT `trainee_code_ledger_code` PRIMARY KEY(`code`)
);
CREATE TABLE IF NOT EXISTS `trainer_salaries` (
	`id` int AUTO_INCREMENT NOT NULL,
	`crdts` varchar(50),
	`trainerName` varchar(255) NOT NULL,
	`month` varchar(7) NOT NULL,
	`salaryEgp` decimal(10,2) NOT NULL DEFAULT '0',
	`notes` varchar(500),
	`createdAt` bigint NOT NULL,
	`updatedAt` bigint NOT NULL,
	CONSTRAINT `trainer_salaries_id` PRIMARY KEY(`id`)
);
CREATE TABLE IF NOT EXISTS `training_batches` (
	`id` int AUTO_INCREMENT NOT NULL,
	`name` varchar(255) NOT NULL,
	`trainerName` varchar(255),
