	`notes` text,
	`createdAt` timestamp NOT NULL DEFAULT (now()),
	`updatedAt` timestamp NOT NULL DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
	CONSTRAINT `training_batches_id` PRIMARY KEY(`id`)
);
CREATE TABLE IF NOT EXISTS `users` (
	`id` int AUTO_INCREMENT NOT NULL,
	`openId` varchar(64) NOT NULL,
	`name` text,
	`email` varchar(320),
	`loginMethod` varchar(64),
	`role` enum('user','admin','owner','manager','hr','ops_manager','team_lead','finance','bd','viewer') NOT NULL DEFAULT 'user',
	`sessionsRevokedAt` bigint,
	`createdAt` timestamp NOT NULL DEFAULT (now()),
	`updatedAt` timestamp NOT NULL DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
	`lastSignedIn` timestamp NOT NULL DEFAULT (now()),
	CONSTRAINT `users_id` PRIMARY KEY(`id`),
	CONSTRAINT `users_openId_unique` UNIQUE(`openId`)
);
CREATE TABLE IF NOT EXISTS `workforce_agents` (
	`id` int AUTO_INCREMENT NOT NULL,
	`traineeCode` varchar(100) NOT NULL,
	`candidateId` int NOT NULL,
	`campaignId` int,
	`fullName` varchar(255) NOT NULL,
	`alias` varchar(100),
	`email` varchar(320),
	`phone` varchar(64),
	`shiftHours` varchar(100),
	`teamLeader` varchar(255),
	`offDay1` int,
	`offDay2` int,
	`joinDate` bigint,
	`dialerCredentials` varchar(500),
	`crdts` varchar(500),
	`agentStatus` enum('active','inactive','frozen','resigned','terminated','blacklisted') NOT NULL DEFAULT 'active',
	`employeeType` enum('agent','team_lead','manager','hr','ops_manager','finance','admin') NOT NULL DEFAULT 'agent',
	`openId` varchar(255),
	`salarySettled` boolean NOT NULL DEFAULT true,
	`address` varchar(500),
	`emergencyContactName` varchar(255),
	`emergencyContactPhone` varchar(64),
	`emergencyContactRelation` varchar(100),
	`settledAt` bigint,
	`nestingStatus` enum('nesting','active','senior') NOT NULL DEFAULT 'nesting',
	`workLocation` enum('office','wfh') NOT NULL DEFAULT 'office',
	`avatarUrl` varchar(1024),
	`nationalId` varchar(50),
	`nationalIdExpiry` varchar(20),
	`contractEndDate` varchar(20),
	`contractStartDate` varchar(20),
	`contractSigned` boolean DEFAULT false,
	`probationEndDate` varchar(20),
	`isOnProbation` boolean DEFAULT false,
	`rehireEligible` boolean DEFAULT true,
	`rehireNote` varchar(500),
	`dateOfBirth` varchar(20),
	`gender` enum('male','female'),
	`nationality` varchar(100),
	`maritalStatus` enum('single','married','divorced','widowed'),
	`militaryStatus` enum('completed','exempt','postponed','not_applicable'),
	`jobTitle` varchar(150),
	`city` varchar(120),
	`profileLocked` boolean NOT NULL DEFAULT false,
	`isActive` boolean NOT NULL DEFAULT true,
	`orientationShown` boolean NOT NULL DEFAULT false,
	`sessionRevokedAt` bigint,
	`isDemo` boolean DEFAULT false,
	`promotedAt` bigint,
	`createdAt` timestamp NOT NULL DEFAULT (now()),
	`updatedAt` timestamp NOT NULL DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
	CONSTRAINT `workforce_agents_id` PRIMARY KEY(`id`),
	CONSTRAINT `workforce_agents_traineeCode_unique` UNIQUE(`traineeCode`)
);

